/**
 * kon-booking
 *
 * Sistema de reservas de salas y recursos con detección de conflictos
 */
export interface BookingApi {
  /**
   * Add a note to a booking
   *
   * Adds a note to a booking: the owner or staff. `isInternal: true` (hidden from the owner) is staff only (403). Someone else's booking is a 404.
   *
   * REST: `POST /api/booking/bookings/{id}/notes` · scope `kon:booking:anotar-reserva`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `booking__anotar-reserva`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly anotarReserva: Operation<AnotarReservaParams, AnotarReservaResponse>;
  /**
   * Remove a blackout period
   *
   * Deletes a blackout period, making the room bookable again in it. Staff only (admin or editor, or an agent with the whole kon).
   *
   * REST: `DELETE /api/booking/blackout/{blackoutId}` · scope `kon:booking:borrar-bloqueo`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `booking__borrar-bloqueo`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly borrarBloqueo: Operation<BorrarBloqueoParams, BorrarBloqueoResponse>;
  /**
   * Delete a room
   *
   * Deletes a room and, in cascade, ALL its bookings, notes, amenity links and blackouts. Cannot be undone. Admin accounts only (editors cannot).
   *
   * REST: `DELETE /api/booking/rooms/{id}` · scope `kon:booking:borrar-sala`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `booking__borrar-sala`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly borrarSala: Operation<BorrarSalaParams, BorrarSalaResponse>;
  /**
   * Cancel a booking
   *
   * Cancels a booking with an optional `reason`. The owner, while it is pending or confirmed; staff, always. Someone else's booking is a 404; a booking its owner can no longer cancel is a 403.
   *
   * REST: `POST /api/booking/bookings/{id}/cancel` · scope `kon:booking:cancelar-reserva`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `booking__cancelar-reserva`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly cancelarReserva: Operation<CancelarReservaParams, CancelarReservaResponse>;
  /**
   * Check whether a room is free
   *
   * Whether a room can be booked between `startTime` and `endTime` (ISO 8601, all three required). If free: the room, the duration and the estimated cost at the room's hourly rate. If not: the reason; staff also get the ids of the clashing bookings and the blackout details.
   *
   * REST: `GET /api/booking/availability` · scope `kon:booking:consultar-disponibilidad`
   * idempotent (safe to retry) · MCP tool `booking__consultar-disponibilidad`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly consultarDisponibilidad: Operation<ConsultarDisponibilidadParams, ConsultarDisponibilidadResponse>;
  /**
   * Block a room for a period
   *
   * Creates a blackout period (`startDate` to `endDate`, ISO 8601, optional reason and recurrence) in which the room cannot be booked. Existing bookings are not touched. Staff only (admin or editor, or an agent with the whole kon).
   *
   * REST: `POST /api/booking/rooms/{id}/blackout` · scope `kon:booking:crear-bloqueo`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `booking__crear-bloqueo`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearBloqueo: Operation<CrearBloqueoParams, CrearBloqueoResponse>;
  /**
   * Book a room
   *
   * Books a room in the caller's name (the user comes from the session, the price from the room). Confirmed at once, or pending when the room requires approval. 404 if the room does not exist or is inactive; 409 if it is not available, overlaps another booking or a blackout; 422 for past times or limits of the room (duration, advance days, capacity).
   *
   * REST: `POST /api/booking/bookings` · scope `kon:booking:crear-reserva`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `booking__crear-reserva`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearReserva: Operation<CrearReservaParams, CrearReservaResponse>;
  /**
   * Create a room
   *
   * Creates a bookable room (name required; slug derived from the name if absent, 409 if taken) and links its amenities (`amenityIds`). Prices come from here, never from a booking. Staff only (admin or editor, or an agent with the whole kon).
   *
   * REST: `POST /api/booking/rooms` · scope `kon:booking:crear-sala`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `booking__crear-sala`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearSala: Operation<CrearSalaParams, CrearSalaResponse>;
  /**
   * Create an amenity
   *
   * Creates an amenity (name, optional icon, description and category) that rooms can then list in `amenityIds`. Staff only (admin or editor, or an agent with the whole kon).
   *
   * REST: `POST /api/booking/amenities` · scope `kon:booking:crear-servicio`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `booking__crear-servicio`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearServicio: Operation<CrearServicioParams, CrearServicioResponse>;
  /**
   * Edit a booking
   *
   * Updates the descriptive fields of a booking. The owner may edit while pending or confirmed and may only change `status` to cancelled; staff may change any status (approve, reject, check-in/out, no-show) and `metadata`/`rejectionReason` (403 for anyone else). Someone else's booking is a 404.
   *
   * REST: `PATCH /api/booking/bookings/{id}` · scope `kon:booking:editar-reserva`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `booking__editar-reserva`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly editarReserva: Operation<EditarReservaParams, EditarReservaResponse>;
  /**
   * Edit a room
   *
   * Partial update of a room (any create field plus `isActive`). `amenityIds`, when sent, replaces the room's amenity list. 409 if the new slug is taken. Staff only (admin or editor, or an agent with the whole kon).
   *
   * REST: `PATCH /api/booking/rooms/{id}` · scope `kon:booking:editar-sala`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `booking__editar-sala`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly editarSala: Operation<EditarSalaParams, EditarSalaResponse>;
  /**
   * Check a booking in
   *
   * Marks a confirmed booking as checked in, recording who did it (from the session). Staff only (403 for the owner); 400 if the booking is not confirmed; someone else's booking is a 404 for a non-staff account.
   *
   * REST: `POST /api/booking/bookings/{id}/check-in` · scope `kon:booking:hacer-check-in`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `booking__hacer-check-in`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly hacerCheckIn: Operation<HacerCheckInParams, HacerCheckInResponse>;
  /**
   * Check a booking out
   *
   * Marks a checked-in booking as checked out. Staff only (403 for the owner); 400 if the booking is not checked in; someone else's booking is a 404 for a non-staff account.
   *
   * REST: `POST /api/booking/bookings/{id}/check-out` · scope `kon:booking:hacer-check-out`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `booking__hacer-check-out`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly hacerCheckOut: Operation<HacerCheckOutParams, HacerCheckOutResponse>;
  /**
   * Blackout periods of a room
   *
   * Periods in which a room cannot be booked, ordered by start (up to 500). Staff also see the reason and who created them.
   *
   * REST: `GET /api/booking/rooms/{id}/blackout` · scope `kon:booking:listar-bloqueos`
   * idempotent (safe to retry) · MCP tool `booking__listar-bloqueos`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarBloqueos: Operation<ListarBloqueosParams, ListarBloqueosResponse>;
  /**
   * Bookable time slots of a room for one day
   *
   * Slots every 30 minutes within the room's opening hours (UTC; 08:00-18:00 by default) for `date` (YYYY-MM-DD, today by default), each lasting `duration` minutes (15-1440, 60 by default), marked available or not. Says nothing about who booked. Public.
   *
   * REST: `GET /api/booking/rooms/{id}/slots` · scope `kon:booking:listar-huecos-de-sala`
   * idempotent (safe to retry) · MCP tool `booking__listar-huecos-de-sala`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarHuecosDeSala: Operation<ListarHuecosDeSalaParams, ListarHuecosDeSalaResponse>;
  /**
   * My upcoming bookings
   *
   * The caller's upcoming bookings (pending, confirmed or checked in, not yet ended), soonest first, with the room name. The user comes from the session; a `userId` in the query is ignored.
   *
   * REST: `GET /api/booking/my-bookings` · scope `kon:booking:listar-mis-reservas`
   * idempotent (safe to retry) · MCP tool `booking__listar-mis-reservas`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarMisReservas: Operation<void, ListarMisReservasResponse>;
  /**
   * List bookings
   *
   * Bookings, newest start first, with the room name. An account sees only ITS OWN (the `userId` filter is ignored for it); staff see everyone's and may filter by `userId`. Other filters: `roomId`, `status`, `startAfter`, `startBefore` (ISO 8601), `limit` (max 100) and `offset`.
   *
   * REST: `GET /api/booking/bookings` · scope `kon:booking:listar-reservas`
   * idempotent (safe to retry) · MCP tool `booking__listar-reservas`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarReservas: PageableOperation<ListarReservasParams, ListarReservasResponse, ListarReservasItem>;
  /**
   * List bookable rooms
   *
   * Active rooms ordered by name (up to 500), with cover and image URLs. Filters: `type`, `minCapacity`, `maxCapacity` and `features` (comma-separated feature keys that must be true). Public.
   *
   * REST: `GET /api/booking/rooms` · scope `kon:booking:listar-salas`
   * idempotent (safe to retry) · MCP tool `booking__listar-salas`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarSalas: Operation<ListarSalasParams, ListarSalasResponse>;
  /**
   * List amenities
   *
   * Active amenities (projector, whiteboard…) ordered by name, up to 500, optionally filtered by `category`. Public.
   *
   * REST: `GET /api/booking/amenities` · scope `kon:booking:listar-servicios`
   * idempotent (safe to retry) · MCP tool `booking__listar-servicios`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarServicios: Operation<ListarServiciosParams, ListarServiciosResponse>;
  /**
   * Read a booking
   *
   * One booking with its room and notes. The owner sees it without staff fields and without internal notes; staff see everything. Someone else's booking is a 404 (its existence is not confirmed).
   *
   * REST: `GET /api/booking/bookings/{id}` · scope `kon:booking:ver-reserva`
   * idempotent (safe to retry) · MCP tool `booking__ver-reserva`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verReserva: Operation<VerReservaParams, VerReservaResponse>;
  /**
   * Read a room
   *
   * One room by id or slug, with its amenities and image URLs. With `include_bookings=true` it adds the next occupied slots: staff get the next 10 confirmed bookings (id, title, times, status); anyone else only start and end times. An inactive room is a 404 except for staff.
   *
   * REST: `GET /api/booking/rooms/{id}` · scope `kon:booking:ver-sala`
   * idempotent (safe to retry) · MCP tool `booking__ver-sala`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verSala: Operation<VerSalaParams, VerSalaResponse>;
}
